import{_ as n,o as e,c as h,a6 as c}from"./chunks/framework.BIQm0xy3.js";const u=JSON.parse('{"title":"Phụ lục C. Bảng đối chiếu: thang điểm đề thi ↔ chương sách","description":"","frontmatter":{"title":"Phụ lục C. Bảng đối chiếu: thang điểm đề thi ↔ chương sách"},"headers":[],"relativePath":"phu-luc-c.md","filePath":"phu-luc-c.md"}'),a={name:"phu-luc-c.md"};function g(i,t,l,r,d,o){return e(),h("div",null,[...t[0]||(t[0]=[c('<p class="eyebrow">Phụ lục C</p><h1 id="bang-đoi-chieu-thang-điem-đe-thi-↔-chuong-sach" tabindex="-1">Bảng đối chiếu: thang điểm đề thi ↔ chương sách <a class="header-anchor" href="#bang-đoi-chieu-thang-điem-đe-thi-↔-chuong-sach" aria-label="Permalink to &quot;Bảng đối chiếu: thang điểm đề thi ↔ chương sách&quot;">​</a></h1><p>Tổng hợp từ 12 đề thi thực hành của hai học kỳ gần nhất. Cột “Có ở” là số đề chứa mục đó.</p><table tabindex="0"><thead><tr><th>Mục chấm trong đề thi</th><th style="text-align:center;">Có ở</th><th style="text-align:center;">Điểm</th><th style="text-align:center;">Học ở</th></tr></thead><tbody><tr><td>Chia file rõ ràng (.h, .cpp, main.cpp, đúng tên)</td><td style="text-align:center;">12/12</td><td style="text-align:center;">2</td><td style="text-align:center;"><a href="./chuong-1.html">Chương 1</a></td></tr><tr><td>Chương trình chạy đúng, test case hợp lý</td><td style="text-align:center;">12/12</td><td style="text-align:center;">2 – 3</td><td style="text-align:center;"><a href="./chuong-1.html">Chương 1</a>, 8</td></tr><tr><td>Thiết kế đúng lớp, kế thừa đầy đủ</td><td style="text-align:center;">12/12</td><td style="text-align:center;">2</td><td style="text-align:center;">Chương 2, 4</td></tr><tr><td>Dùng đúng hàm ảo và override</td><td style="text-align:center;">12/12</td><td style="text-align:center;">1 – 2</td><td style="text-align:center;">Chương 5</td></tr><tr><td>Đa hình hoạt động đúng với con trỏ</td><td style="text-align:center;">12/12</td><td style="text-align:center;">1</td><td style="text-align:center;">Chương 5</td></tr><tr><td>UML / comment rõ ràng (bonus)</td><td style="text-align:center;">12/12</td><td style="text-align:center;">+2</td><td style="text-align:center;">Chương 2</td></tr><tr><td>Bắt và xử lý đúng ngoại lệ</td><td style="text-align:center;">8/12</td><td style="text-align:center;">1</td><td style="text-align:center;">Chương 7</td></tr><tr><td>Tính trừu tượng</td><td style="text-align:center;">4/12</td><td style="text-align:center;">1</td><td style="text-align:center;">Chương 6</td></tr><tr><td>Tính đóng gói (private/protected + getter/setter)</td><td style="text-align:center;">4/12</td><td style="text-align:center;">1</td><td style="text-align:center;">Chương 3</td></tr><tr><td>Hàm khởi tạo đúng</td><td style="text-align:center;">4/12</td><td style="text-align:center;">1</td><td style="text-align:center;">Chương 2, 4</td></tr></tbody></table><h2 id="đoc-bang-nay-the-nao" tabindex="-1">Đọc bảng này thế nào <a class="header-anchor" href="#đoc-bang-nay-the-nao" aria-label="Permalink to &quot;Đọc bảng này thế nào&quot;">​</a></h2><div class="hop ghi-chu"><p><strong>Bốn dòng đầu có ở mọi đề và cộng lại là 7 – 9 điểm.</strong> Nếu thời gian ôn tập có hạn, ôn <a href="./chuong-1.html">chương 1</a>, 2, 4, 5 trước. Chương 3, 6, 7 chỉ 1 điểm mỗi chương — quan trọng để hiểu hệ thống, nhưng không phải chỗ ăn điểm lớn nhất.</p><p><strong><a href="./chuong-1.html">Chương 1</a> một mình đã gánh 4 – 5 điểm.</strong> Đây là chương duy nhất mà luyện tay chắc chắn có kết quả, và là chương sinh viên hay bỏ qua nhất vì tưởng nó “không phải OOP”.</p><p><strong>UML 2 điểm thưởng có ở 12/12 đề.</strong> Với trung bình lớp đang là 4.8, bỏ trắng mục này là quyết định đắt nhất mà một sinh viên có thể đưa ra trong phòng thi.</p></div><p>Toàn bộ mã nguồn trong sách nằm ở <code>TH/2026/dap_an/</code> (hệ thống thư viện, tám giai đoạn theo tám chương), <code>TH/2026/giaotrinh/vi_du/de_thi_vehicle/</code> (lời giải đề thi ở <a href="./chuong-8.html">chương 8</a>) và <code>TH/2026/giaotrinh/vi_du/luyen_uml/</code> (6 bài luyện của <a href="./chuong-9.html">chương 9</a>). Tất cả đã được biên dịch và chạy thật bằng g++ 15.2 với <code>-Wall -Wextra</code> — mọi khối “kết quả” trong sách là output thật, không phải gõ tay.</p>',7)])])}const y=n(a,[["render",g]]);export{u as __pageData,y as default};
